/**
 * Convert any Japanese string containing Kanji into Sino-Vietnamese (Hán Việt) reading.
 * Example: getHanViet("次回") => "THỨ HỒI"
 * Example: getHanViet("日本語") => "NHẬT BẢN NGỮ"
 * Example: getHanViet("ありがとう") => ""
 * 
 * @param {string} text
 * @returns {string} Hán Việt uppercase string, or empty if no Kanji found
 */
export const getHanViet = (text) => {
  if (!text || typeof text !== 'string') return '';

  const kanjiChars = text.match(/[\u4e00-\u9faf]/g);
  if (!kanjiChars || kanjiChars.length === 0) return '';

  const readings = [];
  for (const char of kanjiChars) {
    if (KANJI_HANVIET_MAP[char]) {
      readings.push(KANJI_HANVIET_MAP[char]);
    }
  }

  return readings.join(' ');
};

/**
 * Check if text contains any Kanji character.
 * @param {string} text
 * @returns {boolean}
 */
export const containsKanji = (text) => /[\u4e00-\u9faf]/.test(text);

export default {
  KANJI_HANVIET_MAP,
  getHanViet,
  containsKanji
};
